(function ($) {

	// A custom jQuery UI widget for horizontally scrolling content areas.
	// This component manages dynamic content, user interactions, and automated scrolling.
	$.widget("scrollMaster.flowPane", {
		// Define the default configuration settings for the flow pane instance.
		options: {
			// CSS classes assigned to structural elements generated by this component.
			leftBoundaryClass: "scrollBoundaryLeft",
			rightBoundaryClass: "scrollBoundaryRight",
			leftBoundaryActiveIndicator: "scrollBoundaryLeftActive",
			rightBoundaryActiveIndicator: "scrollBoundaryRightActive",
			contentRegionClass: "scrollContentArea",
			viewPortClass: "scrollViewport",

			// General operational parameters.
			initiallyConcealed: false,
			initialContentFetch: null, // Expects an object { method: "...", content: "...", ... }
			filterableItemSelector: "", // Selector for items to count or manage in continuous mode.
			initialElementID: "", // ID of an element to scroll to on initialization.

			// Configuration for interaction with boundary hot-spots.
			boundaryInteractionEnabled: true,
			boundaryScrollIncrement: 15, // Pixels moved per step when hovering over a boundary.
			boundaryScrollDelay: 10, // Milliseconds between scroll steps.
			boundaryClickBoostFactor: 3, // Multiplier for scroll speed when mouse button is down.
			boundaryDisplayMode: "hover", // "always", "onStart", "hover", or "" (never visible).
			boundaryDisplayDuration: 5000, // Milliseconds boundaries remain visible if 'onStart'.
			easeOutAfterBoundaryScroll: true, // Apply easing effect after boundary scroll stops.
			easeOutBoundaryDistance: 10, // Pixels for easing effect.
			easeOutBoundaryTime: 300, // Milliseconds for easing effect.
			easeOutBoundaryFunction: "easeOutQuart", // Easing function name.

			// Configuration for mouse wheel scrolling.
			wheelScrollDirection: "", // "vertical", "horizontal", "allDirections", or "" (disabled).
			wheelScrollIncrement: 70, // Pixels per mouse wheel notch.
			easeOutAfterWheelScroll: true, // Apply easing after mouse wheel scroll.
			easeOutWheelTime: 300, // Milliseconds for easing effect.
			easeOutWheelFunction: "easeOutQuart", // Easing function name.

			// Settings for continuous looping scroll modes.
			loopingScrollMode: false,

			// Configuration for automatic scrolling.
			automaticScrollBehavior: "", // "always", "onStart", or "" (disabled).
			automaticScrollPath: "endlessLoopRight", // "right", "left", "backAndForth", "endlessLoopRight", "endlessLoopLeft".
			automaticScrollIncrement: 1, // Pixels per step for auto-scrolling.
			automaticScrollDelay: 10, // Milliseconds between auto-scroll steps.

			// Touch gesture scrolling.
			touchGestureEnabled: false,

			// Easing for programmatic scrolling to a specific element.
			jumpToElementAnimationDuration: 1000, // Milliseconds for scroll-to-element animation.
			jumpToElementEasingFunction: "easeOutQuart" // Easing function name.
		},

		// _initializeComponent is called once when the widget is instantiated.
		_initializeComponent: function () {
			const instance = this;
			const config = this.options;
			const rootElement = this.element;

			// Store references to internal elements in the root element's data cache.
			// This helps avoid repeated DOM lookups.
			rootElement.data({
				paneContainer: rootElement.find("." + config.viewPortClass),
				rightBoundaryElement: rootElement.find("." + config.rightBoundaryClass),
				leftBoundaryElement: rootElement.find("." + config.leftBoundaryClass),
				contentRegionElement: rootElement.find("." + config.contentRegionClass),
				scrollMultiplier: 1, // Speed booster for hot-spot scrolling.
				currentXScrollRate: 0, // Current calculated scroll speed for hot-spots.
				boundaryZoneWidth: 0, // Width of the hot-spot elements.
				contentRegionTotalWidth: 0, // Total width of the scrollable content.
				initialScrollOffset: 0, // Starting scroll position.
				rightScrollTimer: null, // Timer for right hot-spot scrolling.
				leftScrollTimer: null, // Timer for left hot-spot scrolling.
				autoScrollTimer: null, // Timer for automatic scrolling.
				boundaryHideTimer: null, // Timer to hide hot-spot backgrounds.
				lastKnownScrollPosition: 0, // Used for continuous scrolling checks.
				autoScrollDirectionState: "right", // For 'backAndForth' auto-scrolling.
				fetchNextItemWidth: true, // Flag for continuous scrolling.
				contentSwapPoint: null, // Position for content swapping in continuous mode.
				initialElementNotReached: true, // Flag for initial element positioning.
				lastSwappedItem: null, // Reference to the last element swapped.
				initialContentItems: rootElement.data("contentRegionElement").children(config.filterableItemSelector), // Original children.
				isDisplaying: true, // Visibility state of the component.
				isOperational: true, // Enabled/disabled state.
				contentRegionHeight: 0, // Height of the content area.
				componentOffset: rootElement.offset() // Offset of the main component.
			});

			// Helper function to ensure core structural elements exist.
			const ensureStructure = () => {
				let viewport = rootElement.data("paneContainer");
				let contentArea = rootElement.data("contentRegionElement");

				if (contentArea.length === 0 && viewport.length === 0) {
					// Both viewport and content area are missing, create both.
					rootElement.wrapInner(`<div class='${config.contentRegionClass}'>`).wrapInner(`<div class='${config.viewPortClass}'>`);
				} else if (viewport.length === 0) {
					// Only viewport is missing, wrap content.
					rootElement.wrapInner(`<div class='${config.viewPortClass}'>`);
				} else if (contentArea.length === 0) {
					// Only content area is missing, wrap children inside viewport.
					viewport.wrapInner(`<div class='${config.contentRegionClass}'>`);
				}

				// Update stored references after potential creation.
				rootElement.data("paneContainer", rootElement.find("." + config.viewPortClass));
				rootElement.data("contentRegionElement", rootElement.find("." + config.contentRegionClass));
			};

			// Detach existing hot-spots if they are present, to re-insert them later.
			rootElement.data("rightBoundaryElement").detach();
			rootElement.data("leftBoundaryElement").detach();

			// Verify and create necessary wrapper elements.
			ensureStructure();

			// Re-insert or create the hot-spot elements.
			const createOrPrependBoundary = (isRight) => {
				const className = isRight ? config.rightBoundaryClass : config.leftBoundaryClass;
				const dataKey = isRight ? "rightBoundaryElement" : "leftBoundaryElement";
				let boundaryElement = rootElement.data(dataKey);

				if (boundaryElement.length === 0) {
					rootElement.prepend(`<div class='${className}'></div>`);
					boundaryElement = rootElement.find("." + className);
					rootElement.data(dataKey, boundaryElement);
				} else {
					rootElement.prepend(boundaryElement);
				}
			};
			createOrPrependBoundary(true); // Right boundary
			createOrPrependBoundary(false); // Left boundary

			// Capture the width of the boundary zones for calculations.
			rootElement.data("boundaryZoneWidth", rootElement.data("leftBoundaryElement").innerWidth());

			// --- Event Binding for Touch Scrolling ---
			if (config.touchGestureEnabled && rootElement.data("isOperational")) {
				// Utilize jquery.kinetic.js for touch interactions.
				rootElement.data("paneContainer").kinetic({
					y: false, // Disable vertical scrolling.
					moved: function () {
						if (config.loopingScrollMode) {
							// Check for continuous loop conditions.
							if (rootElement.data("paneContainer").scrollLeft() <= 0) {
								instance._manageLeftLoopingSwap();
							} else {
								instance._manageRightLoopingSwap();
							}
						}
						instance._emitEvent("touchMoved");
					},
					stopped: function () {
						// Halt any ongoing animations and auto-scrolling.
						rootElement.data("paneContainer").stop(true, false);
						instance.haltAutoScrolling();
						instance._emitEvent("touchStopped");
					}
				});
			}

			// --- Event Binding for Right Boundary (Hot-Spot) Scrolling ---
			const rightBoundary = rootElement.data("rightBoundaryElement");
			rightBoundary.on("mousemove", function (evt) {
				if (!config.boundaryInteractionEnabled) return;
				let cursorX = evt.pageX - $(this).offset().left;
				rootElement.data("currentXScrollRate", Math.round((cursorX / rootElement.data("boundaryZoneWidth")) * config.boundaryScrollIncrement));
				// Ensure scroll rate is at least 1.
				if (rootElement.data("currentXScrollRate") < 1 || !isFinite(rootElement.data("currentXScrollRate"))) {
					rootElement.data("currentXScrollRate", 1);
				}
			});

			rightBoundary.on("mouseover", function () {
				if (!config.boundaryInteractionEnabled) return;
				// Stop active animations and auto-scrolling.
				rootElement.data("paneContainer").stop(true, false);
				instance.haltAutoScrolling();

				// Start the continuous scroll timer.
				rootElement.data("rightScrollTimer", setInterval(function () {
					const currentScrollRate = rootElement.data("currentXScrollRate");
					const scrollBoost = rootElement.data("scrollMultiplier");
					const viewport = rootElement.data("paneContainer");
					
					if (currentScrollRate > 0 && rootElement.data("isOperational")) {
						viewport.scrollLeft(viewport.scrollLeft() + (currentScrollRate * scrollBoost));
						if (config.loopingScrollMode) {
							instance._manageRightLoopingSwap();
						}
						instance._adjustBoundaryVisibility();
					}
				}, config.boundaryScrollDelay));
				instance._emitEvent("mouseOverRightBoundary");
			});

			rightBoundary.on("mouseout", function () {
				if (!config.boundaryInteractionEnabled) return;
				clearInterval(rootElement.data("rightScrollTimer"));
				rootElement.data("currentXScrollRate", 0);

				// Apply easing effect if configured.
				if (config.easeOutAfterBoundaryScroll && rootElement.data("isOperational")) {
					rootElement.data("paneContainer").animate({
						scrollLeft: rootElement.data("paneContainer").scrollLeft() + config.easeOutBoundaryDistance
					}, {
						duration: config.easeOutBoundaryTime,
						easing: config.easeOutBoundaryFunction
					});
				}
			});

			rightBoundary.on("mousedown", function () {
				rootElement.data("scrollMultiplier", config.boundaryClickBoostFactor);
			});

			// --- Event Binding for Left Boundary (Hot-Spot) Scrolling ---
			const leftBoundary = rootElement.data("leftBoundaryElement");
			leftBoundary.on("mousemove", function (evt) {
				if (!config.boundaryInteractionEnabled) return;
				let cursorX = rootElement.data("boundaryZoneWidth") - (evt.pageX - $(this).offset().left);
				rootElement.data("currentXScrollRate", Math.round((cursorX / rootElement.data("boundaryZoneWidth")) * config.boundaryScrollIncrement));
				// Ensure scroll rate is at least 1.
				if (rootElement.data("currentXScrollRate") < 1 || !isFinite(rootElement.data("currentXScrollRate"))) {
					rootElement.data("currentXScrollRate", 1);
				}
			});

			leftBoundary.on("mouseover", function () {
				if (!config.boundaryInteractionEnabled) return;
				// Stop active animations and auto-scrolling.
				rootElement.data("paneContainer").stop(true, false);
				instance.haltAutoScrolling();

				// Start the continuous scroll timer.
				rootElement.data("leftScrollTimer", setInterval(function () {
					const currentScrollRate = rootElement.data("currentXScrollRate");
					const scrollBoost = rootElement.data("scrollMultiplier");
					const viewport = rootElement.data("paneContainer");

					if (currentScrollRate > 0 && rootElement.data("isOperational")) {
						viewport.scrollLeft(viewport.scrollLeft() - (currentScrollRate * scrollBoost));
						if (config.loopingScrollMode) {
							instance._manageLeftLoopingSwap();
						}
						instance._adjustBoundaryVisibility();
					}
				}, config.boundaryScrollDelay));
				instance._emitEvent("mouseOverLeftBoundary");
			});

			leftBoundary.on("mouseout", function () {
				if (!config.boundaryInteractionEnabled) return;
				clearInterval(rootElement.data("leftScrollTimer"));
				rootElement.data("currentXScrollRate", 0);

				// Apply easing effect if configured.
				if (config.easeOutAfterBoundaryScroll && rootElement.data("isOperational")) {
					rootElement.data("paneContainer").animate({
						scrollLeft: rootElement.data("paneContainer").scrollLeft() - config.easeOutBoundaryDistance
					}, {
						duration: config.easeOutBoundaryTime,
						easing: config.easeOutBoundaryFunction
					});
				}
			});

			leftBoundary.on("mousedown", function () {
				rootElement.data("scrollMultiplier", config.boundaryClickBoostFactor);
			});

			// Reset scroll speed multiplier when mouse button is released anywhere on the body.
			$("body").on("mouseup", function () {
				rootElement.data("scrollMultiplier", 1);
			});

			// --- Event Binding for Mouse Wheel Scrolling ---
			rootElement.data("contentRegionElement").on("mousewheel", function (evt, wheelDelta, wheelDeltaX, wheelDeltaY) {
				if (!rootElement.data("isOperational") || !config.wheelScrollDirection) return;

				let scrollPixels;
				const scrollDirection = config.wheelScrollDirection;

				// Prevent default browser scrolling behavior for the mouse wheel.
				evt.preventDefault();

				// Determine scroll amount based on configuration and wheel input.
				if (scrollDirection === "vertical" && wheelDeltaY !== 0) {
					scrollPixels = Math.round((config.wheelScrollIncrement * wheelDeltaY) * -1);
				} else if (scrollDirection === "horizontal" && wheelDeltaX !== 0) {
					scrollPixels = Math.round((config.wheelScrollIncrement * wheelDeltaX) * -1);
				} else if (scrollDirection === "allDirections") {
					scrollPixels = Math.round((config.wheelScrollIncrement * wheelDelta) * -1);
				} else {
					return; // No matching scroll direction, do nothing.
				}

				// Stop auto-scrolling before manual wheel movement.
				instance.haltAutoScrolling();
				instance.shiftView(scrollPixels);
			});

			// Suppress mousewheel events over boundary hot-spots if wheel scrolling is enabled.
			if (config.wheelScrollDirection) {
				leftBoundary.add(rightBoundary).on("mousewheel", function (evt) {
					evt.preventDefault();
				});
			}

			// --- Event Binding for Window Resizing ---
			$(window).on("resize", function () {
				instance._adjustBoundaryVisibility();
				instance._emitEvent("windowResized");
			});

			// --- Initial Content Fetching ---
			// If initialContentFetch is configured, execute the specified method.
			const initialFetch = config.initialContentFetch;
			if (initialFetch && typeof initialFetch.method === 'string' && instance[initialFetch.method]) {
				instance[initialFetch.method](
					initialFetch.content,
					initialFetch.manipulationMethod,
					initialFetch.addWhere,
					initialFetch.filterTag
				);
			}

			// Hide the component if initiallyConcealed is true.
			if (config.initiallyConcealed) {
				instance.hide();
			}

			// --- Post-Load Initialization (ensures element widths are correctly calculated) ---
			// The $(window).load event is used to ensure all images and content are loaded,
			// allowing accurate width calculations.
			$(window).on("load", function () {
				// Recalculate content area dimensions if not hidden.
				if (!config.initiallyConcealed) {
					instance.recomputeContentDimensions();
				}

				// Start auto-scrolling if enabled and not hidden.
				if (config.automaticScrollBehavior && !config.initiallyConcealed) {
					instance.startAutoScrolling();
				}

				// Manage visibility of boundary indicators based on configuration.
				if (config.automaticScrollBehavior !== "always") {
					switch (config.boundaryDisplayMode) {
						case "always":
							instance.displayBoundaryIndicators();
							break;
						case "onStart":
							instance.displayBoundaryIndicators();
							rootElement.data("boundaryHideTimer", setTimeout(function () {
								instance.concealBoundaryIndicators(250);
							}, config.boundaryDisplayDuration));
							break;
						case "hover":
							rootElement.on("mouseenter", function (evt) {
								if (config.boundaryInteractionEnabled) {
									evt.stopPropagation();
									instance.displayBoundaryIndicators(250);
								}
							}).on("mouseleave", function (evt) {
								if (config.boundaryInteractionEnabled) {
									evt.stopPropagation();
									instance.concealBoundaryIndicators(250);
								}
							});
							break;
						default:
							// No specific action, boundaries remain hidden by default.
							break;
					}
				}

				// Adjust boundary visibility based on content width.
				instance._adjustBoundaryVisibility();
				instance._emitEvent("setupComplete");
			});
		},

		// _reInitializeContent is called when the widget is invoked without arguments,
		// typically after external content changes.
		_reInitializeContent: function () {
			const instance = this;
			// Re-calculate the total width of elements within the content area.
			instance.recomputeContentDimensions();
			// Re-evaluate and adjust the visibility of scrolling boundaries.
			instance._adjustBoundaryVisibility();
			// Trigger a callback to indicate re-initialization is complete.
			instance._emitEvent("reinitializationComplete");
		},

		// _updateConfiguration handles changes to widget options after initialization.
		_updateConfiguration: function (key, value) {
			const instance = this;
			const config = this.options;
			const rootElement = this.element;

			// Always update the option value first.
			config[key] = value;

			if (key === "boundaryInteractionEnabled") {
				// If boundary interaction is disabled, hide the boundaries.
				if (value === true) {
					instance._adjustBoundaryVisibility();
				} else {
					rootElement.data("leftBoundaryElement").hide();
					rootElement.data("rightBoundaryElement").hide();
				}
			} else if (key === "automaticScrollIncrement" ||
				key === "easeOutBoundaryDistance" ||
				key === "easeOutBoundaryTime" ||
				key === "easeOutWheelTime") {
				// Ensure these values are treated as integers.
				config[key] = parseInt(value, 10);
			} else if (key === "automaticScrollDelay") {
				// Update interval and restart auto-scrolling if delay changes.
				config[key] = parseInt(value, 10);
				instance.startAutoScrolling();
			}

			// Call the default _setOption to ensure standard handling.
			this._super(key, value);
		}
		// Additional methods (recomputeContentDimensions, _adjustBoundaryVisibility,
		// startAutoScrolling, haltAutoScrolling, displayBoundaryIndicators,
		// concealBoundaryIndicators, shiftView, _manageLeftLoopingSwap,
		// _manageRightLoopingSwap, _emitEvent, etc.) would be implemented here,
		// with similar renaming and structural changes.
	});
})(jQuery);